 }

 QList<Inhibition> ServerPrivate::externalInhibitions() const
@@ -541,6 +553,112 @@ void ServerPrivate::clearExternalInhibitions()

     Q_EMIT externalInhibitedChanged();
     Q_EMIT externalInhibitionsChanged();
+
+    saveExternalInhibitions();
+}
+
+QString ServerPrivate::inhibitionsStatePath() const
+{
+    // The bus ID makes sure we never restore inhibitions from another session,
+    // since unique service names are only meaningful on the bus they were given out on
+    const QDBusMessage busIdReply = QDBusConnection::sessionBus().call(QDBusMessage::createMethodCall(QStringLiteral("org.freedesktop.DBus"),
+                                                                                                      QStringLiteral("/org/freedesktop/DBus"),
+                                                                                                      QStringLiteral("org.freedesktop.DBus"),
+                                                                                                      QStringLiteral("GetId")));
+    if (busIdReply.type() != QDBusMessage::ReplyMessage || busIdReply.arguments().isEmpty()) {
+        return {};
+    }
+
+    const QString runtimeDir = QStandardPaths::writableLocation(QStandardPaths::RuntimeLocation);
+    if (runtimeDir.isEmpty()) {
+        return {};
+    }
+
+    return runtimeDir + QLatin1String("/plasma-notification-inhibitions-") + busIdReply.arguments().constFirst().toString();
+}
+
+void ServerPrivate::saveExternalInhibitions() const
+{
+    const QString path = inhibitionsStatePath();
+    if (path.isEmpty()) {
+        return;
+    }
+
+    if (m_externalInhibitions.isEmpty()) {
+        QFile::remove(path);
+        return;
+    }
+
+    QSaveFile file(path);
+    if (!file.open(QIODevice::WriteOnly)) {
+        qCWarning(NOTIFICATIONMANAGER) << "Failed to save inhibitions to" << path << file.errorString();
+        return;
+    }
+
+    QDataStream stream(&file);
+    stream << m_highestInhibitionCookie << qsizetype(m_externalInhibitions.count());
+    for (auto it = m_externalInhibitions.cbegin(), end = m_externalInhibitions.cend(); it != end; ++it) {
+        stream << it.key() << m_inhibitionServices.value(it.key()) << it->desktopEntry << it->applicationName << it->reason << it->hints;
+    }
+
+    if (!file.commit()) {
+        qCWarning(NOTIFICATIONMANAGER) << "Failed to save inhibitions to" << path << file.errorString();
+    }
+}
+
+void ServerPrivate::restoreExternalInhibitions()
+{
+    // Applications only inhibit once, so if we were restarted (e.g. after a crash)
+    // restore the inhibitions whose applications are still around
+    const QString path = inhibitionsStatePath();
+    if (path.isEmpty()) {
+        return;
+    }
+
+    QFile file(path);
+    if (!file.open(QIODevice::ReadOnly)) {
+        return;
+    }
+
+    QDataStream stream(&file);
+    uint highestCookie = 0;
+    qsizetype count = 0;
+    stream >> highestCookie >> count;
+
+    const bool oldExternalInhibited = externalInhibited();
+
+    for (qsizetype i = 0; i < count && stream.status() == QDataStream::Ok; ++i) {
+        uint cookie = 0;
+        QString service;
+        Inhibition inhibition;
+        stream >> cookie >> service >> inhibition.desktopEntry >> inhibition.applicationName >> inhibition.reason >> inhibition.hints;
+        if (stream.status() != QDataStream::Ok || service.isEmpty()) {
+            break;
+        }
+
+        m_inhibitionWatcher->addWatchedService(service);
+        if (!QDBusConnection::sessionBus().interface()->isServiceRegistered(service)) {
+            m_inhibitionWatcher->removeWatchedService(service);
+            continue;
+        }
+
+        qCDebug(NOTIFICATIONMANAGER) << "Restoring inhibition from service" << service << "which is" << inhibition.desktopEntry << "with reason"
+                                     << inhibition.reason;
+        m_externalInhibitions.insert(cookie, inhibition);
+        m_inhibitionServices.insert(cookie, service);
+    }
+    file.close();
+
+    m_highestInhibitionCookie = std::max(m_highestInhibitionCookie, highestCookie);
+
+    if (externalInhibited() != oldExternalInhibited) {
+        Q_EMIT externalInhibitedChanged();
+    }
+    if (!m_externalInhibitions.isEmpty()) {
+        Q_EMIT externalInhibitionsChanged();
+    }
+
+    saveExternalInhibitions();
 }

